    term_ids = [self.term_dict.get_term_id(token) for token in tokens]

    # Get positions of each term in the document
    positions = self.posns.positions(term_ids)

    # Initialize a 2D array to store phrase frequencies
    phrase_freqs = np.zeros((len(self), len(tokens)), dtype=int)

    # Iterate over documents and tokens
    for doc_id, pos in enumerate(positions):
        # Initialize a set to store unique phrases in the document
        phrases = set()

        # Iterate over token positions
        for i, token_pos in enumerate(pos):
            # Generate phrases of length 2 to len(tokens)
            for j in range(i + 1, len(pos)):
                phrase = tuple(sorted([token_pos, pos[j]]))

                # Add the phrase to the set if it's not already there
                if phrase not in phrases:
                    phrases.add(phrase)

        # Update the phrase frequencies array
        for phrase in phrases:
            phrase_freqs[doc_id, :len(phrase)] += 1

    # Return the phrase frequencies array
    return phrase_freqs.sum(axis=1)

